# >>> STATIC
_static_install_upgrade_strategy() {
    cat <<-'ARGCEOF'
	eager	dependencies are upgraded regardless of whether the currently installed version satisfies the requirements of the upgraded package(s)
	only-if-needed	are upgraded only when they do not satisfy the requirements of the upgraded package(s)
ARGCEOF
}

_static_inspect_exists_action() {
    cat <<-'ARGCEOF'
	s	switch
	i	ignore
	w	wipe
	b	backup
	a	abort
ARGCEOF
}

_static_list_exists_action() {
    cat <<-'ARGCEOF'
	s	switch
	i	ignore
	w	wipe
	b	backup
	a	abort
ARGCEOF
}

_static_check_exists_action() {
    cat <<-'ARGCEOF'
	s	switch
	i	ignore
	w	wipe
	b	backup
	a	abort
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_cache_pattern() {
    pip cache list --format=abspath 2>/dev/null | sed -e 's|.*/||'
}

_choice_config_key() {
    pip config list 2>/dev/null | sed -n 's/^\([A-Za-z][^=]*\)=.*/\1/p' | _argc_util_comp_parts .
}

_choice_exists_action() {
    cat <<-'EOF'
	s	switch
	i	ignore
	w	wipe
	b	backup
	a	abort
	EOF
}

_choice_format_control() {
    cat <<-'EOF' | _argc_util_comp_multi ,
	:all:	all packages
	:none:	no packages
	EOF
}

_choice_installed_package() {
    _argc_util_cache 60 _choice_installed_package_uncached
}

_choice_installed_package_uncached() {
    pip list --format=freeze 2>/dev/null | gawk -F= 'NF > 1 { print $1 }'
}

_choice_refresh_package() {
    cat <<-'EOF' | _argc_util_comp_multi ,
	:all:	all packages
	EOF
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
